"""Generate the generic action AI list for TV IO establishment actions."""

import argparse
import sys
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

import yaml

REPO_ROOT = Path(__file__).resolve().parents[4]
DATA_FILE = REPO_ROOT / "data" / "io_establishment.yaml"
OUT_FILE = (
    REPO_ROOT
    / "src"
    / "in_game"
    / "common"
    / "generic_action_ai_lists"
    / "tv_io_establishment_list.txt"
)

HEADER = """\
# @Generated by scripts/in_game/common/generic_action_ai_lists/gen_tv_io_establishment_list.py
#   Data:    data/io_establishment.yaml
#   Regen:   conda run --no-capture-output -n eu5 python scripts/in_game/common/generic_action_ai_lists/gen_tv_io_establishment_list.py
# Do not edit directly - modify the data file and re-run the generator.
"""


def sorted_paths(data: dict) -> list[dict]:
    return sorted(data["paths"], key=lambda path: int(path.get("order", 0)))


def action_ids(data: dict) -> list[str]:
    ids: list[str] = []
    for path in sorted_paths(data):
        pid = path["id"]
        ids.append(f"tv_build_{pid}_headquarters")
        ids.append(f"tv_establish_{pid}_io")
    return ids


def generate(data: dict) -> str:
    lines = [HEADER.rstrip(), "", "tv_io_establishment_list = {"]
    lines.append("\tpotential = {")
    lines.append("\t\tOR = {")
    for path in sorted_paths(data):
        pid = path["id"]
        lines.append("\t\t\tAND = {")
        lines.append(f"\t\t\t\ttv_{pid}_establishment_basic_done = yes")
        lines.append(f"\t\t\t\tNOT = {{ has_variable = tv_{pid}_victory_enabled }}")
        lines.append("\t\t\t}")
    lines.append("\t\t}")
    lines.append("\t}")
    lines.append("\tactions = {")
    for action_id in action_ids(data):
        lines.append(f"\t\t{action_id}")
    lines.append("\t}")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry", action="store_true", help="Print to stdout instead of writing")
    args = parser.parse_args()

    with DATA_FILE.open(encoding="utf-8") as file:
        data = yaml.safe_load(file)

    content = generate(data)
    if args.dry:
        print(content)
    else:
        OUT_FILE.parent.mkdir(parents=True, exist_ok=True)
        OUT_FILE.write_text(content, encoding="utf-8-sig")
        print(f"Written: {OUT_FILE.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
